#!/bin/sh
# 플레이테스트 상태 한 줄(배속 진행 없음)
node playtest/do.mjs eval "(() => { const s = window.__pc(); const pl=s.plHistory.slice(-1)[0]||{}; const u=Object.values(s.markets).reduce((a,m)=>a+m.users,0); return s.day+' '+(s.ended?'ENDED ':'')+'users '+Math.round(u)+' bugs '+Math.round(s.product.bugs)+' aw '+s.markets.kr.awareness.toFixed(3)+' cash '+Math.round(s.cash/1e4)+'만 emp '+s.employees.length+' stage '+s.company.stage+' fund '+s.fundingStage+' road '+s.product.roadmap.length+' rev '+Math.round((pl.revenue||0)/1e4)+'만 net '+Math.round((pl.netIncome||0)/1e4)+'만 val '+Math.round(s.valuation.stored/1e8)+'억 apps '+s.applicants.filter(a=>a.status==='waiting').length+' open '+s.decisions.filter(d=>!d.resolved).length+' office '+s.company.officeTier; })()" | sed 's/.*"value":"\([^"]*\)".*/\1/'
